window.products.push({"id":534244,"name":"VacMaster Vacuum Canister Container 1/2-Quart for Vacuum Packaging","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/41GBmz1KIHL._AC_.jpg","description":"Our VacMaster Canister is perfect for food storage, keeping foods fresh up to five times longer. Their durable design and graduation marks it perfect for portion control and table-ready dishes. Plus, they are stackable, making storage a snap and the Lock and Vacuum features ensures secure and dependable seal. The VacMaster Canister is microwave and refrigerator safe making it convenient, easy to use and ideal to move, store, or place on the counter top for easy access.","images":["https://m.media-amazon.com/images/I/41GBmz1KIHL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Vacmaster","source_asin":"B0061R554C","category_path":"Home & Kitchen"},"sku":"BM-534244","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B0061R554C","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B0061R554C","price_pending":true,"merchant_ready":false});
